-- Run on a disposable migrated Supabase database. Every fixture rolls back.
begin;
insert into auth.users(id,email) values ('10000000-0000-0000-0000-000000000001','host@example.test'),('10000000-0000-0000-0000-000000000002','stranger@example.test'),('10000000-0000-0000-0000-000000000003','friend@example.test');
do $$
declare created jsonb; rsvp jsonb; retry jsonb; snapshot jsonb; result jsonb; token text; invite text; party_id uuid; need_id uuid; claim_id uuid; pledge_id uuid; second_token text; second_guest uuid; failed boolean;
begin
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 created:=public.party_api('createParty',jsonb_build_object('title','Security test party','hostName','Alex Test','coverUrl','https://images.example.test/party.jpg','startsAt',now()-interval '1 day','endsAt',now()-interval '20 hours','address','Hidden street','budgetCents',30000,'needs',jsonb_build_array(jsonb_build_object('title','Last ice bag','kind','item','quantity',1,'estimatedValueCents',500)),'idempotencyKey',gen_random_uuid()));
 party_id:=(created->'party'->>'id')::uuid; invite:=created->>'inviteToken'; need_id:=(created->'party'->'needs'->0->>'id')::uuid;
 perform set_config('request.jwt.claim.sub','',true);
 snapshot:=public.party_api('invitation',jsonb_build_object('inviteToken',invite));
 assert snapshot->>'address' is null,'Invitation leaked private address';
 assert snapshot->>'coverUrl'='https://images.example.test/party.jpg','Cover URL roundtrip failed';
 assert snapshot->>'hostName'='Alex Test','Host display name not saved';
 result:=jsonb_build_object('inviteToken',invite,'name','Guest one','status','going','idempotencyKey',gen_random_uuid());
 rsvp:=public.party_api('rsvp',result); retry:=public.party_api('rsvp',result);
 assert rsvp=retry,'Retry changed guest/token result'; token:=rsvp->>'managementToken';
 failed:=false; begin perform public.party_api('rsvp',result||'{"name":"Changed request"}'::jsonb); exception when others then failed:=true; end; assert failed,'Same idempotency key accepted a changed request';
 assert (select count(*)=1 from public.guests where guests.party_id=(created->'party'->>'id')::uuid),'Duplicate RSVP';
 snapshot:=public.party_api('guest',jsonb_build_object('managementToken',token));
 assert snapshot->'party'->>'address'='Hidden street','Validated guest missing address';
 perform public.party_api('changeRsvp',jsonb_build_object('managementToken',token,'name','Updated guest','idempotencyKey',gen_random_uuid()));
 snapshot:=public.party_api('guest',jsonb_build_object('managementToken',token));
 assert snapshot->'guest'->>'name'='Updated guest','Guest name update failed';
 failed:=false; begin perform public.party_api('guest','{"managementToken":"forged"}'); exception when insufficient_privilege then failed:=true; end; assert failed,'Forged capability accepted';
 result:=public.party_api('claim',jsonb_build_object('managementToken',token,'needId',need_id,'quantity',1,'idempotencyKey',gen_random_uuid())); claim_id:=(result->>'id')::uuid;
 result:=public.party_api('rsvp',jsonb_build_object('inviteToken',invite,'name','Another guest','status','maybe','idempotencyKey',gen_random_uuid())); second_token:=result->>'managementToken'; second_guest:=(result->'guest'->>'id')::uuid;
 failed:=false; begin perform public.party_api('releaseClaim',jsonb_build_object('managementToken',second_token,'claimId',claim_id,'idempotencyKey',gen_random_uuid())); exception when others then failed:=true; end; assert failed,'Guest released another guest claim';
 failed:=false; begin perform public.party_api('claim',jsonb_build_object('managementToken',token,'needId',need_id,'quantity',1,'idempotencyKey',gen_random_uuid())); exception when others then failed:=true; end; assert failed,'Overclaim accepted';
 result:=public.party_api('pledge',jsonb_build_object('managementToken',token,'coverRemaining',true,'idempotencyKey',gen_random_uuid())); pledge_id:=(result->>'id')::uuid;
 assert (result->>'amountCents')::integer=30000,'Funding snapshot incorrect';
 snapshot:=public.party_api('invitation',jsonb_build_object('inviteToken',invite)); assert (snapshot->>'confirmedCents')::integer=0,'Pledge counted as received';
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 failed:=false; begin failed:=false; begin perform public.party_api('updateParty',jsonb_build_object('partyId',party_id,'coverUrl','javascript:alert(1)','idempotencyKey',gen_random_uuid())); exception when check_violation then failed:=true; end; assert failed,'Unsafe cover URL accepted';
 result:=public.party_api('updateParty',jsonb_build_object('partyId',party_id,'coverUrl','https://images.example.test/updated.jpg','idempotencyKey',gen_random_uuid()));
 assert result->'party'->>'coverUrl'='https://images.example.test/updated.jpg','Cover update failed';
 perform public.party_api('confirmPayment',jsonb_build_object('pledgeId',pledge_id,'idempotencyKey',gen_random_uuid())); exception when insufficient_privilege then failed:=true; end; assert failed,'Cross-host payment confirmation accepted';
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 failed:=false; begin perform public.party_api('updateParty',jsonb_build_object('partyId',party_id,'coverUrl','javascript:alert(1)','idempotencyKey',gen_random_uuid())); exception when check_violation then failed:=true; end; assert failed,'Unsafe cover URL accepted';
 result:=public.party_api('updateParty',jsonb_build_object('partyId',party_id,'coverUrl','https://images.example.test/updated.jpg','idempotencyKey',gen_random_uuid()));
 assert result->'party'->>'coverUrl'='https://images.example.test/updated.jpg','Cover update failed';
 perform public.party_api('confirmPayment',jsonb_build_object('pledgeId',pledge_id,'idempotencyKey',gen_random_uuid()));
 perform public.party_api('verifyClaim',jsonb_build_object('claimId',claim_id,'idempotencyKey',gen_random_uuid()));
 perform public.party_api('revokeGuest',jsonb_build_object('guestId',second_guest,'idempotencyKey',gen_random_uuid()));
 perform set_config('request.jwt.claim.sub','',true);
 failed:=false; begin perform public.party_api('guest',jsonb_build_object('managementToken',second_token)); exception when insufficient_privilege then failed:=true; end; assert failed,'Revoked management token remained valid';
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 result:=public.party_api('finalize',jsonb_build_object('partyId',party_id,'idempotencyKey',gen_random_uuid()));
 assert (result->>'auraAwarded')::integer=0,'Aura without independent linked participants';
 assert (select count(*)=count(distinct activity_key) from public.score_events),'Duplicate score awards';
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 perform public.party_api('linkGuest',jsonb_build_object('managementToken',token,'idempotencyKey',gen_random_uuid()));
 assert (select prestige=305 from public.score_summaries where profile_id='10000000-0000-0000-0000-000000000002'),'Previous contributions did not link to profile';
 assert (select reputation is null from public.score_summaries where profile_id='10000000-0000-0000-0000-000000000002'),'Low confidence reputation should remain Unrated';
 perform public.reverse_score((select id from public.score_events where activity_key='money:'||pledge_id),'Test payment correction');
 assert (select prestige=5 from public.score_summaries where profile_id='10000000-0000-0000-0000-000000000002'),'Reversal failed to remove original award';
 failed:=false; begin update public.score_events set value=1000; exception when others then failed:=true; end; assert failed,'Immutable ledger allowed mutation';
 raise notice 'Backend integrity assertions passed';
end $$;
do $$
declare created jsonb; guest_result jsonb; invite text; token text; party_id uuid; guest_id uuid; participant uuid; final_payload jsonb; finalized jsonb;
begin
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 created:=public.party_api('createParty',jsonb_build_object('title','Verified real gathering','startsAt',now()-interval '1 day','endsAt',now()-interval '20 hours','idempotencyKey',gen_random_uuid()));
 party_id:=(created->'party'->>'id')::uuid; invite:=created->>'inviteToken';
 foreach participant in array array['10000000-0000-0000-0000-000000000002'::uuid,'10000000-0000-0000-0000-000000000003'::uuid] loop
 perform set_config('request.jwt.claim.sub','',true);
 guest_result:=public.party_api('rsvp',jsonb_build_object('inviteToken',invite,'name','Verified participant','status','going','idempotencyKey',gen_random_uuid()));
 token:=guest_result->>'managementToken'; guest_id:=(guest_result->'guest'->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',participant::text,true);
 perform public.party_api('linkGuest',jsonb_build_object('managementToken',token,'idempotencyKey',gen_random_uuid()));
 perform public.party_api('confirmAttendance',jsonb_build_object('managementToken',token,'idempotencyKey',gen_random_uuid()));
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 perform public.party_api('attendance',jsonb_build_object('guestId',guest_id,'attended',true,'idempotencyKey',gen_random_uuid()));
 end loop;
 final_payload:=jsonb_build_object('partyId',party_id,'idempotencyKey',gen_random_uuid());
 finalized:=public.party_api('finalize',final_payload);
 assert (finalized->>'verifiedParticipants')::integer=2,'Independent participants missing';
 assert (finalized->>'auraAwarded')::integer=14,'Aura square-root formula incorrect';
 assert finalized=public.party_api('finalize',final_payload),'Finalization retry not idempotent';
 assert (select aura=14 from public.score_summaries where profile_id='10000000-0000-0000-0000-000000000001'),'Host Aura summary incorrect';
 assert not has_function_privilege('authenticated','public.refresh_scores()','execute'),'Browser can refresh global scores directly';
 assert not has_function_privilege('anon','public.party_snapshot(uuid,boolean,boolean)','execute'),'Private snapshot helper exposed';
 assert not has_function_privilege('authenticated','public.reverse_score(uuid,text)','execute'),'Host can reverse own scores';
 raise notice 'Scoring, account linking, independent attendance, reversal, and finalization replay assertions passed';
end $$;
-- Direct table reads/writes must remain denied even for a signed-in browser.
set local role anon;
do $$ declare failed boolean:=false; begin begin perform 1 from public.guests; exception when insufficient_privilege then failed:=true; end; assert failed,'Anon read sensitive guest table'; end $$;
reset role;
set local role authenticated;
do $$ declare failed boolean:=false; begin begin update public.pledges set status='confirmed'; exception when insufficient_privilege then failed:=true; end; assert failed,'Authenticated browser forged payment'; end $$;
reset role;
rollback;
